pragma solidity ^0.8.4;

/*                                                                    
   DIGITAL ASSET MORTGAGES FOR EVERYONE
   CLIMB THE DIGITAL PROPERTY LADDER
                                                 .@@.                           
                                              @@@@@@.                           
                                          @@@@@@@@@@.                           
                          @@@@@       .@@@@@@@@@@@@@.                           
                          @@@@@    @@@@@@@@@@@@@@@@@.                           
                          @@@@@         @@         @.                           
                          @@&    @@        #@@      .                           
