    function decrease(
        uint8 _orderBookId,
        address _user,
        uint256 _amount,
        uint256 _maturity
    ) external {
        IFutureValueVault(futureValueVaults[_orderBookId]).decrease(
            _orderBookId,
            _user,
            _amount,
            _maturity
        );
    }

