pragma solidity 0.8.19;

import {IBeaconProxyController} from "../../protocol/interfaces/IBeaconProxyController.sol";
import {ILendingMarket} from "../../protocol/interfaces/ILendingMarket.sol";
import {ItayoseFinalizeResult, ItayoseProcessStatus, ItayoseSettlementResult} from "../../protocol/libraries/logics/OrderBookLogic.sol";
import {ProtocolTypes} from "../../protocol/types/ProtocolTypes.sol";

contract LendingMarketCaller {
    IBeaconProxyController public beaconProxyController;
    mapping(bytes32 => address) public lendingMarkets;
    mapping(bytes32 => uint8) public orderBookIdLists;

    constructor(address _beaconProxyController) {
        beaconProxyController = IBeaconProxyController(_beaconProxyController);
    }

    function getLendingMarket(bytes32 _ccy) external view returns (address) {
        return lendingMarkets[_ccy];
    }

    function getOrderBookId(bytes32 _ccy) external view returns (uint8) {
        return orderBookIdLists[_ccy];
    }

    function deployLendingMarket(
        bytes32 _ccy,
        uint256 _orderFeeRate,
        uint256 _limitRange
    ) external {
        lendingMarkets[_ccy] = beaconProxyController.deployLendingMarket(
            _ccy,
            _orderFeeRate,
            _limitRange
        );
    }

    function createOrderBook(
        bytes32 _ccy,
        uint256 _maturity,
        uint256 _openingDate,
        uint256 _preOpeningDate
    ) external {
        orderBookIdLists[_ccy] = ILendingMarket(lendingMarkets[_ccy]).createOrderBook(
            _maturity,
            _openingDate,
            _preOpeningDate
        );
    }

    function updateMinPreOrderAmount(bytes32 _ccy, uint256 _minPreOrderAmount) external {
        ILendingMarket(lendingMarkets[_ccy]).updateMinPreOrderAmount(_minPreOrderAmount);
    }

    function executeAutoRoll(
        bytes32 _ccy,
        uint8 _maturedOrderBookId,
        uint8 _destinationOrderBookId,
        uint256 _autoRollUnitPrice
    ) external {
        ILendingMarket(lendingMarkets[_ccy]).executeAutoRoll(
            _maturedOrderBookId,
            _destinationOrderBookId,
            _autoRollUnitPrice
        );
    }

    function executeOrder(
        bytes32 _ccy,
        uint8 _orderBookId,
        ProtocolTypes.Side _side,
        uint256 _amount,
        uint256 _unitPrice
    ) external {
        ILendingMarket(lendingMarkets[_ccy]).executeOrder(
            _orderBookId,
            _side,
            msg.sender,
            _amount,
            _unitPrice
        );
    }

    function executePreOrder(
        bytes32 _ccy,
        uint8 _orderBookId,
        ProtocolTypes.Side _side,
        uint256 _amount,
        uint256 _unitPrice
    ) external {
        ILendingMarket(lendingMarkets[_ccy]).executePreOrder(
            _orderBookId,
            _side,
            msg.sender,
            _amount,
            _unitPrice
        );
    }

    function unwindPosition(
        bytes32 _ccy,
        uint8 _orderBookId,
        ProtocolTypes.Side _side,
        uint256 _futureValue
    ) external {
        ILendingMarket(lendingMarkets[_ccy]).unwindPosition(
            _orderBookId,
            _side,
            msg.sender,
            _futureValue
        );
    }

    function cancelOrder(
        bytes32 _ccy,
        uint8 _orderBookId,
        address _user,
        uint48 _orderId
    ) external {
        ILendingMarket(lendingMarkets[_ccy]).cancelOrder(_orderBookId, _user, _orderId);
    }

    function initializeItayose(
        bytes32 _ccy,
        uint8 _orderBookId
    ) external returns (ItayoseProcessStatus memory) {
        return ILendingMarket(lendingMarkets[_ccy]).initializeItayose(_orderBookId);
    }

    function executeItayoseSettlement(
        bytes32 _ccy,
        uint8 _orderBookId
    ) external returns (ItayoseSettlementResult memory) {
        return ILendingMarket(lendingMarkets[_ccy]).executeItayoseSettlement(_orderBookId);
    }

    function finalizeItayose(
        bytes32 _ccy,
        uint8 _orderBookId
    ) external returns (ItayoseFinalizeResult memory) {
        return ILendingMarket(lendingMarkets[_ccy]).finalizeItayose(_orderBookId);
    }

    function getItayoseProcessStatus(
        bytes32 _ccy,
        uint8 _orderBookId
    ) external view returns (ItayoseProcessStatus memory) {
        return ILendingMarket(lendingMarkets[_ccy]).getItayoseProcessStatus(_orderBookId);
    }

    function cleanUpOrders(bytes32 _ccy, uint8 _orderBookId, address _user) external {
        ILendingMarket(lendingMarkets[_ccy]).cleanUpOrders(_orderBookId, _user);
    }

    function pause(bytes32 _ccy) external {
        ILendingMarket(lendingMarkets[_ccy]).pause();
    }

    function unpause(bytes32 _ccy) external {
        ILendingMarket(lendingMarkets[_ccy]).unpause();
    }
}

