// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.19;

// dependencies
import {EnumerableSet} from "../../../dependencies/openzeppelin/utils/structs/EnumerableSet.sol";
import {SafeCast} from "../../../dependencies/openzeppelin/utils/math/SafeCast.sol";
// interfaces
import {ILendingMarket} from "../../interfaces/ILendingMarket.sol";
import {ILendingMarketController} from "../../interfaces/ILendingMarketController.sol";
import {IFutureValueVault} from "../../interfaces/IFutureValueVault.sol";
import {IZCToken} from "../../interfaces/IZCToken.sol";
// libraries
import {AddressResolverLib} from "../AddressResolverLib.sol";
import {Constants} from "../Constants.sol";
import {FilledOrder, PartiallyFilledOrder} from "../OrderBookLib.sol";
import {RoundingUint256} from "../math/RoundingUint256.sol";
import {LendingMarketOperationLogic} from "./LendingMarketOperationLogic.sol";
import {FundManagementLogic} from "./FundManagementLogic.sol";
// types
import {ProtocolTypes} from "../../types/ProtocolTypes.sol";
// storages
import {LendingMarketControllerStorage as Storage} from "../../storages/LendingMarketControllerStorage.sol";

library LendingMarketUserLogic {
    using EnumerableSet for EnumerableSet.Bytes32Set;
    using EnumerableSet for EnumerableSet.UintSet;
    using SafeCast for int256;
    using SafeCast for uint256;
    using RoundingUint256 for uint256;

    error InvalidAmount();
    error InvalidPreOrderUnitPrice();
    error AmountIsZero();
    error FutureValueIsZero();
    error TooManyActiveOrders();
    error TooManyDepositCurrencies();
    error NotEnoughCollateral();
    error NotEnoughDeposit(bytes32 ccy);

    struct EstimateCollateralCoverageParams {
        bytes32 ccy;
        uint256 maturity;
        address user;
        ProtocolTypes.Side side;
        uint256 unitPrice;
        uint256 additionalDepositAmount;
        bool ignoreBorrowedAmount;
        uint256 filledAmount;
        uint256 filledAmountInFV;
        uint256 orderFeeInFV;
        uint256 placedAmount;
    }

    function getOrderEstimation(
        ILendingMarketController.GetOrderEstimationParams memory input
    )
        external
        view
        returns (
            uint256 lastUnitPrice,
            uint256 filledAmount,
            uint256 filledAmountInFV,
            uint256 orderFeeInFV,
            uint256 placedAmount,
            uint256 coverage,
            bool isInsufficientDepositAmount
        )
    {
        (
            lastUnitPrice,
            filledAmount,
            filledAmountInFV,
            orderFeeInFV,
            placedAmount
        ) = _calculateFilledAmount(
            input.ccy,
            input.maturity,
            input.side,
            input.amount,
            input.unitPrice
        );

        (coverage, isInsufficientDepositAmount) = _estimateCollateralCoverage(
            EstimateCollateralCoverageParams(
                input.ccy,
                input.maturity,
                input.user,
                input.side,
                input.unitPrice,
                input.additionalDepositAmount,
                input.ignoreBorrowedAmount,
                filledAmount,
                filledAmountInFV,
                orderFeeInFV,
                placedAmount
            )
        );
    }

    function getOrderEstimationFromFV(
        ILendingMarketController.GetOrderEstimationFromFVParams memory input
    )
        external
        view
        returns (
            uint256 lastUnitPrice,
            uint256 filledAmount,
            uint256 filledAmountInFV,
            uint256 orderFeeInFV,
            uint256 coverage,
            bool isInsufficientDepositAmount
        )
    {
        (
            lastUnitPrice,
            filledAmount,
            filledAmountInFV,
            orderFeeInFV
        ) = _calculateFilledAmountFromFV(input.ccy, input.maturity, input.side, input.amountInFV);

        (coverage, isInsufficientDepositAmount) = _estimateCollateralCoverage(
            EstimateCollateralCoverageParams(
                input.ccy,
                input.maturity,
                input.user,
                input.side,
                0, // unitPrice
                input.additionalDepositAmount,
                input.ignoreBorrowedAmount,
                filledAmount,
                filledAmountInFV,
                orderFeeInFV,
                0 // placedAmount
            )
        );
    }

    function executeOrder(
        bytes32 _ccy,
        uint256 _maturity,
        address _user,
        ProtocolTypes.Side _side,
        uint256 _amount,
        uint256 _unitPrice
    ) external {
        LendingMarketOperationLogic.validateOrderUnitPrice(_ccy, _maturity, _side, _unitPrice);
        if (_amount == 0) revert InvalidAmount();

        uint256 activeOrderCount = FundManagementLogic.cleanUpFunds(_ccy, _user);

        bool isNewCurrency = FundManagementLogic.registerCurrencyAndMaturity(
            _ccy,
            _maturity,
            _user
        );

        if (_side == ProtocolTypes.Side.BORROW && isNewCurrency) {
            // Check if the deposit currency can be added for borrow orders because borrowed currency is added as a new deposit currency.
            // NOTE: Even if this check works, deposit currencies can exceed the max `MAX_DEPOSIT_CURRENCIES` due to the lazy evaluation feature.
            // However, it will always be less than or equal to `MAX_DEPOSIT_CURRENCIES` + `MAX_EXPOSURE_CURRENCIES`.
            // To save calculation gas costs, this gap is allowed.
            if (!AddressResolverLib.tokenVault().canDepositCurrency(_user, _ccy)) {
                revert TooManyDepositCurrencies();
            }
        }

        (
            FilledOrder memory filledOrder,
            PartiallyFilledOrder memory partiallyFilledOrder,
            uint256 feeInFV
        ) = ILendingMarket(Storage.slot().lendingMarkets[_ccy]).executeOrder(
                Storage.slot().maturityOrderBookIds[_ccy][_maturity],
                _side,
                _user,
                _amount,
                _unitPrice
            );

        uint256 filledAmount = filledOrder.amount;

        // The case that an order is placed in the order book
        if ((filledAmount + filledOrder.ignoredAmount) != _amount) {
            unchecked {
                activeOrderCount += 1;
            }
        }

        if (activeOrderCount > Constants.MAXIMUM_ORDER_COUNT) revert TooManyActiveOrders();

        if (
            FundManagementLogic.updateFundsForTaker(
                _ccy,
                _maturity,
                _user,
                _side,
                filledAmount,
                filledOrder.futureValue,
                feeInFV
            )
        ) {
            LendingMarketOperationLogic.updateOrderLogs(
                _ccy,
                _maturity,
                filledAmount,
                filledOrder.futureValue
            );
        }

        FundManagementLogic.updateFundsForMaker(
            _ccy,
            _maturity,
            _side == ProtocolTypes.Side.LEND ? ProtocolTypes.Side.BORROW : ProtocolTypes.Side.LEND,
            partiallyFilledOrder
        );

        // Updates the pending order amount for marker's orders.
        // Since the partially filled order is updated with `updateFundsForMaker()`,
        // its amount is subtracted from `pendingOrderAmounts`.
        Storage.slot().pendingOrderAmounts[_ccy][_maturity] +=
            filledAmount -
            partiallyFilledOrder.amount;

        _isCovered(_user, _ccy);
    }

    function executePreOrder(
        bytes32 _ccy,
        uint256 _maturity,
        address _user,
        ProtocolTypes.Side _side,
        uint256 _amount,
        uint256 _unitPrice
    ) external {
        if (_unitPrice == 0) revert InvalidPreOrderUnitPrice();
        LendingMarketOperationLogic.validateOrderUnitPrice(_ccy, _maturity, _side, _unitPrice);
        if (_amount == 0) revert InvalidAmount();

        uint256 activeOrderCount = FundManagementLogic.cleanUpFunds(_ccy, _user);

        if (activeOrderCount + 1 > Constants.MAXIMUM_ORDER_COUNT) revert TooManyActiveOrders();

        bool isNewCurrency = FundManagementLogic.registerCurrencyAndMaturity(
            _ccy,
            _maturity,
            _user
        );

        if (_side == ProtocolTypes.Side.BORROW && isNewCurrency) {
            // Check if the deposit currency can be added for borrow orders
            if (!AddressResolverLib.tokenVault().canDepositCurrency(_user, _ccy)) {
                revert TooManyDepositCurrencies();
            }
        }

        ILendingMarket(Storage.slot().lendingMarkets[_ccy]).executePreOrder(
            Storage.slot().maturityOrderBookIds[_ccy][_maturity],
            _side,
            _user,
            _amount,
            _unitPrice
        );

        _isCovered(_user, _ccy);
    }

    function unwindPosition(
        bytes32 _ccy,
        uint256 _maturity,
        address _user,
        uint256 _maxAmountInFV
    ) external returns (uint256 filledAmount, uint256 filledAmountInFV, uint256 feeInFV) {
        FundManagementLogic.cleanUpFunds(_ccy, _user);

        {
            int256 futureValue = FundManagementLogic
                .getActualFunds(_ccy, _maturity, _user, 0)
                .futureValue;

            // Apply cap if specified
            if (_maxAmountInFV > 0) {
                if (futureValue > 0 && futureValue.toUint256() > _maxAmountInFV) {
                    futureValue = _maxAmountInFV.toInt256();
                } else if (futureValue < 0 && (-futureValue).toUint256() > _maxAmountInFV) {
                    futureValue = -_maxAmountInFV.toInt256();
                }
            }

            FilledOrder memory filledOrder;
            PartiallyFilledOrder memory partiallyFilledOrder;
            ProtocolTypes.Side side;

            (filledOrder, partiallyFilledOrder, feeInFV, side) = _unwindPosition(
                _ccy,
                _maturity,
                _user,
                futureValue
            );

            if (
                FundManagementLogic.updateFundsForTaker(
                    _ccy,
                    _maturity,
                    _user,
                    side,
                    filledOrder.amount,
                    filledOrder.futureValue,
                    feeInFV
                )
            ) {
                LendingMarketOperationLogic.updateOrderLogs(
                    _ccy,
                    _maturity,
                    filledOrder.amount,
                    filledOrder.futureValue
                );
            }

            FundManagementLogic.updateFundsForMaker(
                _ccy,
                _maturity,
                side == ProtocolTypes.Side.LEND
                    ? ProtocolTypes.Side.BORROW
                    : ProtocolTypes.Side.LEND,
                partiallyFilledOrder
            );

            // Updates the pending order amount for marker's orders.
            // Since the partially filled order is updated with `updateFundsForMaker()`,
            // its amount is subtracted from `pendingOrderAmounts`.
            Storage.slot().pendingOrderAmounts[_ccy][_maturity] +=
                filledOrder.amount -
                partiallyFilledOrder.amount;

            filledAmount = filledOrder.amount;
            filledAmountInFV = filledOrder.futureValue;
        }

        // When the market is the nearest market and the user has only GV, a user still has future value after unwinding.
        // For that case, the `registerCurrencyAndMaturity` function needs to be called again.
        (int256 currentFutureValue, ) = IFutureValueVault(Storage.slot().futureValueVaults[_ccy])
            .getBalance(Storage.slot().maturityOrderBookIds[_ccy][_maturity], _user);

        if (currentFutureValue != 0) {
            FundManagementLogic.registerCurrencyAndMaturity(_ccy, _maturity, _user);
        }

        _isCovered(_user, _ccy);
    }

    function withdrawZCToken(
        bytes32 _ccy,
        uint256 _maturity,
        address _user,
        uint256 _amount
    ) public returns (uint256 withdrawnAmount) {
        FundManagementLogic.cleanUpFunds(_ccy, _user);

        if (_maturity == 0) {
            return _withdrawZCPerpetualToken(_ccy, _user, _amount);
        } else {
            return _withdrawZCToken(_ccy, _maturity, _user, _amount);
        }
    }

    function depositZCToken(
        bytes32 _ccy,
        uint256 _maturity,
        address _user,
        uint256 _amount
    ) public {
        FundManagementLogic.cleanUpFunds(_ccy, _user);

        if (_maturity == 0) {
            _depositZCPerpetualToken(_ccy, _user, _amount);
            FundManagementLogic.registerCurrency(_ccy, _user);
        } else {
            _depositZCToken(_ccy, _maturity, _user, _amount);
            FundManagementLogic.registerCurrencyAndMaturity(_ccy, _maturity, _user);
        }
    }

    function getWithdrawableZCTokenAmount(
        bytes32 _ccy,
        uint256 _maturity,
        address _user
    ) public view returns (uint256 amount) {
        if (_maturity == 0) {
            return _getWithdrawableZCPerpetualTokenAmount(_ccy, _user);
        } else {
            return _getWithdrawableZCTokenAmount(_ccy, _maturity, _user);
        }
    }

    function _calculateFilledAmount(
        bytes32 _ccy,
        uint256 _maturity,
        ProtocolTypes.Side _side,
        uint256 _amount,
        uint256 _unitPrice
    )
        internal
        view
        returns (
            uint256 lastUnitPrice,
            uint256 filledAmount,
            uint256 filledAmountInFV,
            uint256 orderFeeInFV,
            uint256 placedAmount
        )
    {
        (
            lastUnitPrice,
            filledAmount,
            filledAmountInFV,
            orderFeeInFV,
            placedAmount
        ) = ILendingMarket(Storage.slot().lendingMarkets[_ccy]).calculateFilledAmount(
            Storage.slot().maturityOrderBookIds[_ccy][_maturity],
            _side,
            _amount,
            _unitPrice
        );
    }

    function _calculateFilledAmountFromFV(
        bytes32 _ccy,
        uint256 _maturity,
        ProtocolTypes.Side _side,
        uint256 _amountInFV
    )
        internal
        view
        returns (
            uint256 lastUnitPrice,
            uint256 filledAmount,
            uint256 filledAmountInFV,
            uint256 orderFeeInFV
        )
    {
        return
            ILendingMarket(Storage.slot().lendingMarkets[_ccy]).calculateFilledAmountFromFV(
                Storage.slot().maturityOrderBookIds[_ccy][_maturity],
                _side,
                _amountInFV
            );
    }

    function _estimateCollateralCoverage(
        EstimateCollateralCoverageParams memory _params
    ) internal view returns (uint256 coverage, bool isInsufficientDepositAmount) {
        uint256 filledAmountWithFeeInPV = _estimateFilledAmountWithFee(
            _params.ccy,
            _params.maturity,
            _params.side,
            _params.filledAmount,
            _params.filledAmountInFV,
            _params.orderFeeInFV
        );

        ILendingMarketController.AdditionalFunds memory funds;
        funds.ccy = _params.ccy;
        // Store the _additionalDepositAmount in the borrowedAmount,
        // because the borrowedAmount is used as collateral.
        funds.borrowedAmount = _params.additionalDepositAmount;

        if (_params.placedAmount != 0) {
            if (_params.side == ProtocolTypes.Side.BORROW) {
                uint256 minUnitPrice = FundManagementLogic.getCurrentMinDebtUnitPrice(
                    _params.maturity,
                    Storage.slot().minDebtUnitPrices[_params.ccy]
                );

                if (_params.unitPrice >= minUnitPrice) {
                    funds.workingBorrowOrdersAmount = _params.placedAmount;
                } else {
                    // NOTE: The formula is:
                    // futureValue = placedAmount / unitPrice
                    // workingBorrowOrdersAmount = futureValue * minUnitPrice
                    funds.workingBorrowOrdersAmount = (_params.placedAmount * minUnitPrice).div(
                        _params.unitPrice
                    );
                }
            } else {
                funds.workingLendOrdersAmount = _params.placedAmount;
            }
        }

        if (filledAmountWithFeeInPV > 0) {
            if (_params.side == ProtocolTypes.Side.BORROW) {
                if (!_params.ignoreBorrowedAmount) {
                    funds.borrowedAmount += _params.filledAmount;
                }
                funds.debtAmount += filledAmountWithFeeInPV;
            } else {
                funds.lentAmount += _params.filledAmount;
                funds.claimableAmount += filledAmountWithFeeInPV;
            }
        }

        (coverage, isInsufficientDepositAmount) = AddressResolverLib.tokenVault().calculateCoverage(
            _params.user,
            funds
        );
    }

    function _estimateFilledAmountWithFee(
        bytes32 _ccy,
        uint256 _maturity,
        ProtocolTypes.Side side,
        uint256 filledAmount,
        uint256 filledAmountInFV,
        uint256 orderFeeInFV
    ) internal view returns (uint256) {
        if (filledAmountInFV == 0) {
            return 0;
        }

        uint256 filledAmountWithFeeInFV = filledAmountInFV;

        if (side == ProtocolTypes.Side.LEND) {
            filledAmountWithFeeInFV -= orderFeeInFV;
        } else {
            filledAmountWithFeeInFV += orderFeeInFV;
        }

        ILendingMarket lendingMarket = ILendingMarket(Storage.slot().lendingMarkets[_ccy]);
        uint256 minimumReliableAmount = AddressResolverLib
            .currencyController()
            .convertFromBaseCurrency(_ccy, lendingMarket.minimumReliableAmountInBaseCurrency());

        uint256 marketUnitPrice;
        if (filledAmount < minimumReliableAmount) {
            marketUnitPrice = lendingMarket.getMarketUnitPrice(
                Storage.slot().maturityOrderBookIds[_ccy][_maturity]
            );
        }

        if (marketUnitPrice == 0) {
            marketUnitPrice = (filledAmount * Constants.PRICE_DIGIT).div(filledAmountInFV);
        }

        return (filledAmountWithFeeInFV * marketUnitPrice).div(Constants.PRICE_DIGIT);
    }

    function _unwindPosition(
        bytes32 _ccy,
        uint256 _maturity,
        address _user,
        int256 _futureValue
    )
        internal
        returns (
            FilledOrder memory filledOrder,
            PartiallyFilledOrder memory partiallyFilledOrder,
            uint256 feeInFV,
            ProtocolTypes.Side side
        )
    {
        if (_futureValue == 0) revert FutureValueIsZero();

        if (_futureValue > 0) {
            side = ProtocolTypes.Side.BORROW;

            (filledOrder, partiallyFilledOrder, feeInFV) = ILendingMarket(
                Storage.slot().lendingMarkets[_ccy]
            ).unwindPosition(
                    Storage.slot().maturityOrderBookIds[_ccy][_maturity],
                    side,
                    _user,
                    _futureValue.toUint256()
                );
        } else if (_futureValue < 0) {
            side = ProtocolTypes.Side.LEND;

            (filledOrder, partiallyFilledOrder, feeInFV) = ILendingMarket(
                Storage.slot().lendingMarkets[_ccy]
            ).unwindPosition(
                    Storage.slot().maturityOrderBookIds[_ccy][_maturity],
                    side,
                    _user,
                    (-_futureValue).toUint256()
                );
        }
    }

    function _withdrawZCToken(
        bytes32 _ccy,
        uint256 _maturity,
        address _user,
        uint256 _amount
    ) internal returns (uint256 withdrawableAmount) {
        uint8 orderBookId = Storage.slot().maturityOrderBookIds[_ccy][_maturity];
        uint256 maxWithdrawableAmount = _getWithdrawableZCTokenAmount(_ccy, _maturity, _user);

        if (maxWithdrawableAmount < _amount) {
            _amount = maxWithdrawableAmount;
        }

        if (_amount == 0) revert AmountIsZero();

        withdrawableAmount = IFutureValueVault(Storage.slot().futureValueVaults[_ccy]).lock(
            orderBookId,
            _user,
            _amount,
            _maturity
        );
        IZCToken(Storage.slot().zcTokens[_ccy][_maturity]).mint(_user, withdrawableAmount);
    }

    function _depositZCToken(
        bytes32 _ccy,
        uint256 _maturity,
        address _user,
        uint256 _amount
    ) internal {
        IZCToken token = IZCToken(Storage.slot().zcTokens[_ccy][_maturity]);
        uint256 balance = token.balanceOf(_user);

        if (balance == 0) {
            revert AmountIsZero();
        }

        if (balance < _amount) {
            _amount = balance;
        }

        token.burn(_user, _amount);
        IFutureValueVault(Storage.slot().futureValueVaults[_ccy]).unlock(
            Storage.slot().maturityOrderBookIds[_ccy][_maturity],
            _user,
            _amount,
            _maturity
        );
    }

    function _withdrawZCPerpetualToken(
        bytes32 _ccy,
        address _user,
        uint256 _amount
    ) internal returns (uint256 withdrawableAmount) {
        uint256 maxWithdrawableAmount = _getWithdrawableZCPerpetualTokenAmount(_ccy, _user);

        if (maxWithdrawableAmount < _amount) {
            _amount = maxWithdrawableAmount;
        }

        if (_amount == 0) revert AmountIsZero();

        withdrawableAmount = AddressResolverLib.genesisValueVault().lock(_ccy, _user, _amount);
        IZCToken(Storage.slot().zcTokens[_ccy][0]).mint(_user, withdrawableAmount);
    }

    function _depositZCPerpetualToken(bytes32 _ccy, address _user, uint256 _amount) internal {
        IZCToken token = IZCToken(Storage.slot().zcTokens[_ccy][0]);
        uint256 balance = token.balanceOf(_user);

        if (balance == 0) {
            revert AmountIsZero();
        }

        if (balance < _amount) {
            _amount = balance;
        }

        token.burn(_user, _amount);
        AddressResolverLib.genesisValueVault().unlock(_ccy, _user, _amount);
    }

    function _getWithdrawableZCTokenAmount(
        bytes32 _ccy,
        uint256 _maturity,
        address _user
    ) internal view returns (uint256 amount) {
        (uint256 withdrawableAmount, bool hasAllocatedCollateral) = _getWithdrawableAmount(
            _ccy,
            _user
        );

        FundManagementLogic.ActualFunds memory funds = FundManagementLogic.getActualFunds(
            _ccy,
            _maturity,
            _user,
            0
        );
        int256 presentValue = funds.presentValue - funds.genesisValueInPV;
        int256 futureValue = funds.futureValue - funds.genesisValueInFV;

        if (futureValue <= 0 || withdrawableAmount == 0) {
            return 0;
        } else if (!hasAllocatedCollateral || withdrawableAmount >= presentValue.toUint256()) {
            return futureValue.toUint256();
        } else {
            return FundManagementLogic.calculateFVFromPV(_ccy, _maturity, withdrawableAmount);
        }
    }

    function _getWithdrawableZCPerpetualTokenAmount(
        bytes32 _ccy,
        address _user
    ) internal view returns (uint256 amount) {
        (uint256 withdrawableAmount, bool hasAllocatedCollateral) = _getWithdrawableAmount(
            _ccy,
            _user
        );

        FundManagementLogic.ActualFunds memory funds = FundManagementLogic.getActualFunds(
            _ccy,
            0,
            _user,
            0
        );

        if (funds.genesisValue <= 0 || withdrawableAmount == 0) {
            return 0;
        } else if (
            !hasAllocatedCollateral || withdrawableAmount >= funds.genesisValueInPV.toUint256()
        ) {
            return funds.genesisValue.toUint256();
        } else {
            int256 withdrawableAmountInFV = FundManagementLogic.calculateFVFromPV(
                _ccy,
                AddressResolverLib.genesisValueVault().getCurrentMaturity(_ccy),
                withdrawableAmount.toInt256()
            );

            return
                AddressResolverLib
                    .genesisValueVault()
                    .calculateGVFromFV(_ccy, 0, withdrawableAmountInFV)
                    .toUint256();
        }
    }

    function _getWithdrawableAmount(
        bytes32 _ccy,
        address _user
    ) internal view returns (uint256 withdrawableAmount, bool hasAllocatedCollateral) {
        ILendingMarketController.AdditionalFunds memory emptyAdditionalFunds;
        uint256 liquidationThresholdRate = AddressResolverLib
            .tokenVault()
            .getLiquidationThresholdRate();
        ILendingMarketController.CalculatedFunds memory funds = FundManagementLogic.calculateFunds(
            _ccy,
            _user,
            emptyAdditionalFunds,
            liquidationThresholdRate
        );

        uint256[] memory amounts = new uint256[](2);
        (amounts[0], amounts[1], ) = AddressResolverLib.tokenVault().getCollateralDetail(_user);
        amounts = AddressResolverLib.currencyController().convertFromBaseCurrency(_ccy, amounts);

        uint256 totalCollateral = amounts[0];
        uint256 totalUsedCollateral = amounts[1];

        if (totalUsedCollateral == 0) {
            return (totalCollateral, false);
        }

        uint256 haircut = AddressResolverLib.currencyController().getHaircut(_ccy);
        uint256 scaledTotalCollateral = totalCollateral * Constants.PCT_DIGIT;
        uint256 scaledUsedCollateralThreshold = totalUsedCollateral * liquidationThresholdRate;

        if (scaledTotalCollateral <= scaledUsedCollateralThreshold) {
            return (0, funds.unallocatedCollateralAmount != 0);
        }

        uint256 availableAmount = (scaledTotalCollateral - scaledUsedCollateralThreshold).div(
            Constants.PCT_DIGIT
        );

        if (funds.unallocatedCollateralAmount == 0) {
            return (availableAmount, false);
        } else {
            // If the available amount is insufficient, unallocated collateral, which is discounted by a haircut and used between different currencies,
            // is used first. Then, the allocated collateral, which is used to offset positions in the same currency, is used for the rest of the amount.
            // NOTE: The formula is:
            // allocatedCollateralAmount = availableAmount - discountedUnallocatedCollateralAmount
            // totalWithdrawableAmount = allocatedCollateralAmount + unallocatedCollateralAmount

            if (haircut == 0) {
                return (availableAmount + funds.unallocatedCollateralAmount, true);
            } else {
                uint256 discountedUnallocatedCollateralAmount = (funds.unallocatedCollateralAmount *
                    haircut).div(Constants.PCT_DIGIT);

                if (availableAmount < discountedUnallocatedCollateralAmount) {
                    return ((availableAmount * Constants.PCT_DIGIT).div(haircut), true);
                } else {
                    return (
                        availableAmount +
                            funds.unallocatedCollateralAmount -
                            discountedUnallocatedCollateralAmount,
                        true
                    );
                }
            }
        }
    }

    function _isCovered(address _user, bytes32 _ccy) internal view {
        (bool isEnoughCollateral, bool isEnoughDepositInOrderCcy) = AddressResolverLib
            .tokenVault()
            .isCovered(_user, _ccy);

        if (!isEnoughDepositInOrderCcy) revert NotEnoughDeposit(_ccy);
        if (!isEnoughCollateral) revert NotEnoughCollateral();
    }
}

5f5257669f02e7a8e7b18e2a1a95c162730f4e4e.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.19;

// dependencies
import {SafeCast} from "../../../dependencies/openzeppelin/utils/math/SafeCast.sol";
// interfaces
import {IFutureValueVault} from "../../interfaces/IFutureValueVault.sol";
import {ILiquidationReceiver} from "../../interfaces/ILiquidationReceiver.sol";
// libraries
import {AddressResolverLib} from "../AddressResolverLib.sol";
import {FundManagementLogic} from "./FundManagementLogic.sol";
import {RoundingUint256} from "../math/RoundingUint256.sol";
// storages
import {LendingMarketControllerStorage as Storage} from "../../storages/LendingMarketControllerStorage.sol";

library LiquidationLogic {
    using RoundingUint256 for uint256;
    using SafeCast for uint256;
    using SafeCast for int256;

    error NoDebt(address user, bytes32 ccy, uint256 maturity);
    error NoLiquidationAmount(address user, bytes32 ccy);
    error InvalidLiquidation();
    error InvalidCurrency(bytes32 ccy);
    error NotRepaymentPeriod();
    error InsufficientRepayment(
        address executor,
        bytes32 ccy,
        uint256 requiredAmount,
        uint256 untransferredAmount
    );

    struct ExecuteLiquidationVars {
        uint256 liquidationAmountInCollateralCcy;
        uint256 liquidationAmountInDebtCcy;
        uint256 protocolFeeInCollateralCcy;
        uint256 liquidatorFeeInCollateralCcy;
        bool isDefaultMarket;
        uint256 receivedCollateralAmount;
    }

    event LiquidationExecuted(
        address indexed user,
        bytes32 collateralCcy,
        bytes32 indexed debtCcy,
        uint256 indexed debtMaturity,
        uint256 debtAmount
    );

    event ForcedRepaymentExecuted(
        address indexed user,
        bytes32 collateralCcy,
        bytes32 indexed debtCcy,
        uint256 indexed debtMaturity,
        uint256 debtAmount
    );

    function executeLiquidation(
        address _liquidator,
        address _user,
        bytes32 _collateralCcy,
        bytes32 _debtCcy,
        uint256 _debtMaturity
    ) external {
        if (!AddressResolverLib.currencyController().currencyExists(_collateralCcy)) {
            revert InvalidCurrency(_collateralCcy);
        }

        ExecuteLiquidationVars memory vars;

        vars.isDefaultMarket =
            Storage.slot().maturityOrderBookIds[_debtCcy][_debtMaturity] ==
            Storage.slot().orderBookIdLists[_debtCcy][0];

        // In order to liquidate using user collateral, inactive order IDs must be cleaned
        // and converted to actual funds first.
        FundManagementLogic.cleanUpFunds(_collateralCcy, _user);
        FundManagementLogic.cleanUpFunds(_debtCcy, _user);

        uint256 debtAmount = FundManagementLogic
            .getActualFunds(_debtCcy, _debtMaturity, _user, 0)
            .debtAmount;

        if (debtAmount == 0) revert NoDebt(_user, _debtCcy, _debtMaturity);

        (
            vars.liquidationAmountInCollateralCcy,
            vars.protocolFeeInCollateralCcy,
            vars.liquidatorFeeInCollateralCcy
        ) = AddressResolverLib.tokenVault().getLiquidationAmount(
            _user,
            _collateralCcy,
            AddressResolverLib.currencyController().convert(_debtCcy, _collateralCcy, debtAmount)
        );

        if (vars.liquidationAmountInCollateralCcy == 0) {
            revert NoLiquidationAmount(_user, _collateralCcy);
        }

        vars.liquidationAmountInDebtCcy = AddressResolverLib.currencyController().convert(
            _collateralCcy,
            _debtCcy,
            vars.liquidationAmountInCollateralCcy
        );

        // Transfer collateral from users to liquidators and reserve funds.
        vars.receivedCollateralAmount =
            vars.liquidationAmountInCollateralCcy +
            vars.liquidatorFeeInCollateralCcy;

        uint256 untransferredAmount = _transferCollateral(
            _user,
            _liquidator,
            _collateralCcy,
            vars.receivedCollateralAmount
        );

        if (untransferredAmount == 0) {
            _transferCollateral(
                _user,
                address(AddressResolverLib.reserveFund()),
                _collateralCcy,
                vars.protocolFeeInCollateralCcy
            );
        } else if (untransferredAmount > 0) {
            (
                uint256 untransferredAmountInDebtCcy,
                uint256 receivedCollateralAmountInDebtCcy,
                uint256 liquidatorFeeInDebtCcy
            ) = _convertLiquidationAmounts(
                    _collateralCcy,
                    _debtCcy,
                    untransferredAmount,
                    vars.receivedCollateralAmount,
                    vars.liquidatorFeeInCollateralCcy
                );

            // Use reserve funds to cover insolvent amounts if user does not have collateral in other currencies.
            if (
                !AddressResolverLib.reserveFund().isPaused() &&
                AddressResolverLib.tokenVault().getTotalCollateralAmount(_user) == 0
            ) {
                untransferredAmountInDebtCcy = _transferPositionsPerMaturity(
                    address(AddressResolverLib.reserveFund()),
                    _liquidator,
                    _debtCcy,
                    _debtMaturity,
                    untransferredAmountInDebtCcy.toInt256(),
                    vars.isDefaultMarket
                ).toUint256();
            }

            // Adjust the liquidation amount for debt.
            vars.liquidationAmountInDebtCcy = _calculateTransferredAmount(
                receivedCollateralAmountInDebtCcy,
                untransferredAmountInDebtCcy,
                liquidatorFeeInDebtCcy
            );
        }

        if (_liquidator.code.length > 0) {
            if (
                ILiquidationReceiver(_liquidator).executeOperationForCollateral(
                    _liquidator,
                    _user,
                    _collateralCcy,
                    vars.receivedCollateralAmount - untransferredAmount
                ) == false
            ) revert ILiquidationReceiver.InvalidOperationExecution();
        }

        // Transfer the debt from users to liquidators
        if (vars.liquidationAmountInDebtCcy > 0) {
            _transferPositionsPerMaturity(
                _user,
                _liquidator,
                _debtCcy,
                _debtMaturity,
                -vars.liquidationAmountInDebtCcy.toInt256(),
                vars.isDefaultMarket
            );

            if (_liquidator.code.length > 0) {
                if (
                    ILiquidationReceiver(_liquidator).executeOperationForDebt(
                        _liquidator,
                        _user,
                        _collateralCcy,
                        vars.receivedCollateralAmount - untransferredAmount,
                        _debtCcy,
                        _debtMaturity,
                        vars.liquidationAmountInDebtCcy
                    ) == false
                ) revert ILiquidationReceiver.InvalidOperationExecution();
            }
        }

        (bool isEnoughCollateral, ) = AddressResolverLib.tokenVault().isCovered(
            _liquidator,
            bytes32(0)
        );
        if (!isEnoughCollateral) revert InvalidLiquidation();

        emit LiquidationExecuted(
            _user,
            _collateralCcy,
            _debtCcy,
            _debtMaturity,
            vars.liquidationAmountInDebtCcy
        );
    }

    function executeForcedRepayment(
        address _executor,
        address _user,
        bytes32 _collateralCcy,
        bytes32 _debtCcy,
        uint256 _debtMaturity
    ) external {
        if (
            AddressResolverLib.currencyController().currencyExists(_debtCcy) ||
            block.timestamp < _debtMaturity + 1 weeks
        ) {
            revert NotRepaymentPeriod();
        }

        if (!AddressResolverLib.currencyController().currencyExists(_collateralCcy)) {
            revert InvalidCurrency(_collateralCcy);
        }

        // In order to liquidate using user collateral, inactive order IDs must be cleaned
        // and converted to actual funds first.
        FundManagementLogic.cleanUpFunds(_collateralCcy, _user);
        FundManagementLogic.cleanUpFunds(_debtCcy, _user);

        FundManagementLogic.ActualFunds memory funds = FundManagementLogic.getActualFunds(
            _debtCcy,
            _debtMaturity,
            _user,
            0
        );

        if (funds.futureValue >= 0) revert NoDebt(_user, _debtCcy, _debtMaturity);

        uint256 liquidationAmountInDebtCcy = (-funds.futureValue).toUint256();
        uint256 liquidationAmountInCollateralCcy = AddressResolverLib.currencyController().convert(
            _debtCcy,
            _collateralCcy,
            liquidationAmountInDebtCcy
        );

        (
            uint256 protocolFeeInCollateralCcy,
            uint256 liquidatorFeeInCollateralCcy
        ) = AddressResolverLib.tokenVault().calculateLiquidationFees(
                liquidationAmountInCollateralCcy
            );

        uint256 receivedCollateralAmount = liquidationAmountInCollateralCcy +
            liquidatorFeeInCollateralCcy;

        uint256 untransferredAmount = _transferCollateral(
            _user,
            _executor,
            _collateralCcy,
            receivedCollateralAmount
        );

        if (untransferredAmount == 0) {
            _transferCollateral(
                _user,
                address(AddressResolverLib.reserveFund()),
                _collateralCcy,
                protocolFeeInCollateralCcy
            );
        } else {
            (
                uint256 untransferredAmountInDebtCcy,
                uint256 receivedCollateralAmountInDebtCcy,
                uint256 liquidatorFeeInDebtCcy
            ) = _convertLiquidationAmounts(
                    _collateralCcy,
                    _debtCcy,
                    untransferredAmount,
                    receivedCollateralAmount,
                    liquidatorFeeInCollateralCcy
                );

            // Adjust the liquidation amount for debt.
            liquidationAmountInDebtCcy = _calculateTransferredAmount(
                receivedCollateralAmountInDebtCcy,
                untransferredAmountInDebtCcy,
                liquidatorFeeInDebtCcy
            );
        }

        if (_executor.code.length > 0) {
            if (
                ILiquidationReceiver(_executor).executeOperationForCollateral(
                    _executor,
                    _user,
                    _collateralCcy,
                    receivedCollateralAmount - untransferredAmount
                ) == false
            ) revert ILiquidationReceiver.InvalidOperationExecution();

            if (
                ILiquidationReceiver(_executor).executeOperationForDebt(
                    _executor,
                    _user,
                    _collateralCcy,
                    receivedCollateralAmount - untransferredAmount,
                    _debtCcy,
                    _debtMaturity,
                    liquidationAmountInDebtCcy
                ) == false
            ) revert ILiquidationReceiver.InvalidOperationExecution();
        }

        untransferredAmount = AddressResolverLib.tokenVault().transferFrom(
            _debtCcy,
            _executor,
            _user,
            liquidationAmountInDebtCcy
        );

        if (untransferredAmount != 0) {
            revert InsufficientRepayment(
                _executor,
                _debtCcy,
                liquidationAmountInDebtCcy,
                untransferredAmount
            );
        }

        uint256 repaymentAmount = FundManagementLogic.executeRepayment(
            _debtCcy,
            _debtMaturity,
            _user,
            liquidationAmountInDebtCcy
        );

        emit ForcedRepaymentExecuted(
            _user,
            _collateralCcy,
            _debtCcy,
            _debtMaturity,
            repaymentAmount
        );
    }

    function _transferCollateral(
        address _from,
        address _to,
        bytes32 _ccy,
        uint256 _amount
    ) internal returns (uint256 untransferredAmount) {
        untransferredAmount = AddressResolverLib.tokenVault().transferFrom(
            _ccy,
            _from,
            _to,
            _amount
        );

        // If `untransferredAmount` is not 0, the user has not enough deposit in the collateral currency.
        // Therefore, the liquidators and the reserve fund obtain zero-coupon bonds instead of the user's collateral.
        if (untransferredAmount > 0) {
            untransferredAmount = _transferPositionsPerCurrency(
                _from,
                _to,
                _ccy,
                untransferredAmount.toInt256()
            ).toUint256();
        }
    }

    function _transferPositionsPerCurrency(
        address _from,
        address _to,
        bytes32 _ccy,
        int256 _amount
    ) internal returns (int256 untransferredAmount) {
        untransferredAmount = _transferGenesisValue(_from, _to, _ccy, _amount);

        uint256[] memory maturities = FundManagementLogic.getUsedMaturities(_ccy, _from);

        for (uint256 i; i < maturities.length; i++) {
            if (untransferredAmount == 0) {
                break;
            }

            untransferredAmount = _transferFutureValues(
                _from,
                _to,
                _ccy,
                maturities[i],
                untransferredAmount
            );
        }
    }

    function _transferPositionsPerMaturity(
        address _from,
        address _to,
        bytes32 _ccy,
        uint256 _maturity,
        int256 _amount,
        bool _isDefaultMarket
    ) internal returns (int256 untransferredAmount) {
        untransferredAmount = _isDefaultMarket
            ? _transferGenesisValue(_from, _to, _ccy, _amount)
            : _amount;

        untransferredAmount = _transferFutureValues(
            _from,
            _to,
            _ccy,
            _maturity,
            untransferredAmount
        );
    }

    function _transferGenesisValue(
        address _from,
        address _to,
        bytes32 _ccy,
        int256 _amount
    ) internal returns (int256 untransferredAmount) {
        untransferredAmount = _amount;
        bool isDebt = _amount < 0;

        int256 userGVAmount = AddressResolverLib.genesisValueVault().getBalance(_ccy, _from, 0);

        if ((isDebt && userGVAmount < 0) || (!isDebt && userGVAmount > 0)) {
            uint256 currentMaturity = AddressResolverLib.genesisValueVault().getCurrentMaturity(
                _ccy
            );

            int256 gvAmount = AddressResolverLib.genesisValueVault().calculateGVFromFV(
                _ccy,
                0,
                FundManagementLogic.calculateFVFromPV(_ccy, currentMaturity, untransferredAmount)
            );

            if ((isDebt && userGVAmount > gvAmount) || (!isDebt && userGVAmount < gvAmount)) {
                gvAmount = userGVAmount;
            }

            // Due to the negative genesis value, the liquidator's genesis value is decreased.
            AddressResolverLib.genesisValueVault().transferFrom(_ccy, _from, _to, gvAmount);

            untransferredAmount -= FundManagementLogic.calculatePVFromFV(
                _ccy,
                currentMaturity,
                AddressResolverLib.genesisValueVault().calculateFVFromGV(_ccy, 0, gvAmount)
            );

            FundManagementLogic.registerCurrency(_ccy, _to);
        }
    }

    function _transferFutureValues(
        address _from,
        address _to,
        bytes32 _ccy,
        uint256 _maturity,
        int256 _amount
    ) internal returns (int256 untransferredAmount) {
        untransferredAmount = _amount;
        bool isDebt = _amount < 0;

        IFutureValueVault futureValueVault = IFutureValueVault(
            Storage.slot().futureValueVaults[_ccy]
        );
        uint8 orderBookId = Storage.slot().maturityOrderBookIds[_ccy][_maturity];

        (int256 userFVAmount, ) = futureValueVault.getBalance(orderBookId, _from);

        if ((isDebt && userFVAmount < 0) || (!isDebt && userFVAmount > 0)) {
            int256 fvAmount = FundManagementLogic.calculateFVFromPV(
                _ccy,
                _maturity,
                untransferredAmount
            );

            if ((isDebt && userFVAmount > fvAmount) || (!isDebt && userFVAmount < fvAmount)) {
                fvAmount = userFVAmount;
            }

            futureValueVault.transferFrom(orderBookId, _from, _to, fvAmount, _maturity);
            untransferredAmount -= FundManagementLogic.calculatePVFromFV(_ccy, _maturity, fvAmount);

            FundManagementLogic.registerCurrencyAndMaturity(_ccy, _maturity, _to);
        }
    }

    function _convertLiquidationAmounts(
        bytes32 _collateralCcy,
        bytes32 _debtCcy,
        uint256 _untransferredAmount,
        uint256 _receivedCollateralAmount,
        uint256 _liquidatorFeeInCollateralCcy
    )
        internal
        view
        returns (
            uint256 untransferredAmountInDebtCcy,
            uint256 receivedCollateralAmountInDebtCcy,
            uint256 liquidatorFeeInDebtCcy
        )
    {
        uint256[] memory amountsInCollateralCcy = new uint256[](3);
        amountsInCollateralCcy[0] = _untransferredAmount;
        amountsInCollateralCcy[1] = _receivedCollateralAmount;
        amountsInCollateralCcy[2] = _liquidatorFeeInCollateralCcy;

        uint256[] memory amountsInDebtCcy = AddressResolverLib.currencyController().convert(
            _collateralCcy,
            _debtCcy,
            amountsInCollateralCcy
        );

        untransferredAmountInDebtCcy = amountsInDebtCcy[0];
        receivedCollateralAmountInDebtCcy = amountsInDebtCcy[1];
        liquidatorFeeInDebtCcy = amountsInDebtCcy[2];
    }

    function _calculateTransferredAmount(
        uint256 totalAmount,
        uint256 untransferredAmount,
        uint256 feeAmount
    ) internal pure returns (uint256) {
        // NOTE: The formula is:
        // transferredTotalAmount = totalAmount - untransferredAmount;
        // untransferredFeeAmount = feeAmount * (transferredTotalAmount / totalAmount);
        uint256 transferredTotalAmount = totalAmount - untransferredAmount;
        uint256 untransferredFeeAmount = (feeAmount * transferredTotalAmount).div(totalAmount);

        return transferredTotalAmount - untransferredFeeAmount;
    }
}

