    // @param key the key of the order
    // @param order the order that was frozen
    function afterOrderFrozen(
        bytes32 key,
        Order.Props memory order,
        EventUtils.EventLogData memory eventData
    ) external {
        if (!isValidCallbackContract(order.callbackContract())) { return; }

        EventUtils.EventLogData memory orderData = OrderEventUtils.createEventData(order);

        validateGasLeftForCallback(order.callbackGasLimit());

        try IOrderCallbackReceiver(order.callbackContract()).afterOrderFrozen{ gas: order.callbackGasLimit() }(
            key,
            orderData,
            eventData
        ) {
        } catch {
            emit AfterOrderFrozenError(key, order);
        }
    }

    // @dev called after a hlvDeposit execution
    // @param key the key of the hlvDeposit
    // @param hlvDeposit the hlvDeposit that was executed
    function afterHlvDepositExecution(
        bytes32 key,
        HlvDeposit.Props memory hlvDeposit,
        EventUtils.EventLogData memory eventData
    ) external {
        if (!isValidCallbackContract(hlvDeposit.callbackContract())) {
            return;
        }

        EventUtils.EventLogData memory hlvData = HlvDepositEventUtils.createEventData(hlvDeposit);

        validateGasLeftForCallback(hlvDeposit.callbackGasLimit());

        try IHlvDepositCallbackReceiver(hlvDeposit.callbackContract()).afterHlvDepositExecution{ gas: hlvDeposit.callbackGasLimit() }(
            key,
            hlvData,
            eventData
        ) {
        } catch {
            emit AfterHlvDepositExecutionError(key, hlvDeposit);
        }
    }

    // @dev called after a hlvDeposit cancellation
    // @param key the key of the hlvDeposit
    // @param hlvDeposit the hlvDeposit that was cancelled
    function afterHlvDepositCancellation(
        bytes32 key,
        HlvDeposit.Props memory hlvDeposit,
        EventUtils.EventLogData memory eventData
    ) external {
        if (!isValidCallbackContract(hlvDeposit.callbackContract())) { return; }

        EventUtils.EventLogData memory hlvData = HlvDepositEventUtils.createEventData(hlvDeposit);

        validateGasLeftForCallback(hlvDeposit.callbackGasLimit());

        try IHlvDepositCallbackReceiver(hlvDeposit.callbackContract()).afterHlvDepositCancellation{ gas: hlvDeposit.callbackGasLimit() }(
            key,
            hlvData,
            eventData
        ) {
        } catch {
            emit AfterHlvDepositCancellationError(key, hlvDeposit);
        }
    }

    // @dev called after a hlvWithdrawal execution
    // @param key the key of the hlvWithdrawal
    // @param hlvWithdrawal the hlvWithdrawal that was executed
    function afterHlvWithdrawalExecution(
        bytes32 key,
        HlvWithdrawal.Props memory hlvWithdrawal,
        EventUtils.EventLogData memory eventData
    ) external {
        if (!isValidCallbackContract(hlvWithdrawal.callbackContract())) { return; }

        EventUtils.EventLogData memory hlvData = HlvWithdrawalEventUtils.createEventData(hlvWithdrawal);

        validateGasLeftForCallback(hlvWithdrawal.callbackGasLimit());

        try IHlvWithdrawalCallbackReceiver(hlvWithdrawal.callbackContract()).afterHlvWithdrawalExecution{ gas: hlvWithdrawal.callbackGasLimit() }(
            key,
            hlvData,
            eventData
        ) {
        } catch {
            emit AfterHlvWithdrawalExecutionError(key, hlvWithdrawal);
        }
    }

    // @dev called after a hlvWithdrawal cancellation
    // @param key the key of the hlvWithdrawal
    // @param hlvWithdrawal the hlvWithdrawal that was cancelled
    function afterHlvWithdrawalCancellation(
        bytes32 key,
        HlvWithdrawal.Props memory hlvWithdrawal,
        EventUtils.EventLogData memory eventData
    ) external {
        if (!isValidCallbackContract(hlvWithdrawal.callbackContract())) { return; }

        EventUtils.EventLogData memory hlvData = HlvWithdrawalEventUtils.createEventData(hlvWithdrawal);

        validateGasLeftForCallback(hlvWithdrawal.callbackGasLimit());

        try IHlvWithdrawalCallbackReceiver(hlvWithdrawal.callbackContract()).afterHlvWithdrawalCancellation{ gas: hlvWithdrawal.callbackGasLimit() }(
            key,
            hlvData,
            eventData
        ) {
        } catch {
            emit AfterHlvWithdrawalCancellationError(key, hlvWithdrawal);
        }
    }

    // @dev validates that the given address is a contract
    // @param callbackContract the contract to call
    function isValidCallbackContract(address callbackContract) public view returns (bool) {
        if (callbackContract == address(0)) { return false; }
        if (!callbackContract.isContract()) { return false; }

        return true;
    }
}

