    // @param account the account for which to retrieve the user balance key
    // @param token the token for which to retrieve the user balance key
    // @return key for multichain balance for a given user and token
    function multichainBalanceKey(address account, address token) internal pure returns (bytes32) {
        return keccak256(abi.encode(
            MULTICHAIN_BALANCE,
            account,
            token
        ));
    }

    // @dev key for the claimable fund amount for a specific account and token
    // @param account the account to claim funds for
    // @param token the token to claim
    // @param distributionId the distribution id to claim funds for
    // @return key for claimable fund amount
    function claimableFundsAmountKey(address account, address token, uint256 distributionId) internal pure returns (bytes32) {
        return keccak256(abi.encode(
            CLAIMABLE_FUNDS_AMOUNT,
            account,
            token,
            distributionId
        ));
    }

    // @dev key for the total claimable amount for a specific token
    // @param token the token for which to retrieve the total claimable amount
    // @return key for total claimable amount
    function totalClaimableFundsAmountKey(address token) internal pure returns (bytes32) {
        return keccak256(abi.encode(
            TOTAL_CLAIMABLE_FUNDS_AMOUNT,
            token
        ));
    }

    function claimTermsKey(uint256 distributionId) internal pure returns (bytes32) {
        return keccak256(abi.encode(
            CLAIM_TERMS,
            distributionId
        ));
    }

    function claimTermsBackrefKey(bytes32 termsHash) internal pure returns (bytes32) {
        return keccak256(abi.encode(
            CLAIM_TERMS_BACKREF,
            termsHash
        ));
    }

    // @dev key for the Credit Token (体验金) ERC20 contract address
    bytes32 public constant CREDIT_TOKEN = keccak256(abi.encode("CREDIT_TOKEN"));
    // @dev key for the CreditFeeClaimVault address. The vault keeps fee-claim
    //      token rates and claimable accounting in its own storage.
    bytes32 public constant CREDIT_FEE_CLAIM_VAULT = keccak256(abi.encode("CREDIT_FEE_CLAIM_VAULT"));
    // @dev key for the CreditProfitClaimVault settlement token.
    //      Fee-claim wrapper token rates are configured on CreditFeeClaimVault.
    bytes32 public constant CREDIT_PAYOUT_TOKEN = keccak256(abi.encode("CREDIT_PAYOUT_TOKEN"));
    // @dev legacy key prefix retained for compatibility with prior fee-claim accounting.
    bytes32 public constant CREDIT_CLAIMABLE_AMOUNT = keccak256(abi.encode("CREDIT_CLAIMABLE_AMOUNT"));
    // @dev key for the CreditDistributor contract address (user-pull claim flow)
    bytes32 public constant CREDIT_DISTRIBUTOR = keccak256(abi.encode("CREDIT_DISTRIBUTOR"));
    // @dev key prefix for the per-account allocation pushed by the off-chain backend into CreditDistributor.
    //      Distinct from CreditFeeClaimVault's local fee-offset claimable accounting
    //      so the two claimable streams cannot interfere.
    bytes32 public constant CREDIT_DISTRIBUTOR_CLAIMABLE_AMOUNT = keccak256(abi.encode("CREDIT_DISTRIBUTOR_CLAIMABLE_AMOUNT"));
    // @dev key for the CreditProfitClaimVault address that holds the USDT reserve backing
    //      Credit Market PnL atomic-swap settlement. Funded by the project team manually.
    bytes32 public constant CREDIT_PROFIT_CLAIM_VAULT = keccak256(abi.encode("CREDIT_PROFIT_CLAIM_VAULT"));

    function creditTokenKey() internal pure returns (bytes32) {
        return CREDIT_TOKEN;
    }

    function creditFeeClaimVaultKey() internal pure returns (bytes32) {
        return CREDIT_FEE_CLAIM_VAULT;
    }

    function creditPayoutTokenKey() internal pure returns (bytes32) {
        return CREDIT_PAYOUT_TOKEN;
    }

    // @dev key for the claimable amount accrued by an account from credit fee offsets
    // @param account the account to query
    function creditClaimableAmountKey(address account) internal pure returns (bytes32) {
        return keccak256(abi.encode(
            CREDIT_CLAIMABLE_AMOUNT,
            account
        ));
    }

    function creditDistributorKey() internal pure returns (bytes32) {
        return CREDIT_DISTRIBUTOR;
    }

    // @dev key for the per-account allocation in CreditDistributor that the user can pull via claim()
    // @param account the account to query
    function creditDistributorClaimableAmountKey(address account) internal pure returns (bytes32) {
        return keccak256(abi.encode(
            CREDIT_DISTRIBUTOR_CLAIMABLE_AMOUNT,
            account
        ));
    }

    function creditProfitClaimVaultKey() internal pure returns (bytes32) {
        return CREDIT_PROFIT_CLAIM_VAULT;
    }
}

