pragma solidity ^0.8.0;

// @title IReferralStorage
// @dev Interface for multi-level referral storage
interface IReferralStorage {
    // @dev get the owner of a referral code
    function codeOwners(bytes32 _code) external view returns (address);

    // @dev get the referral code of a trader (the code they used to bind their referrer)
    function traderReferralCodes(address _account) external view returns (bytes32);

    // @dev get the tier ID of a user
    function referrerTiers(address _account) external view returns (uint256);

    // @dev get the tier detail (l0, l1, l2 rates in basis points)
    function getTierDetail(uint256 _tierId) external view returns (uint256 l0, uint256 l1, uint256 l2);

    // @dev get the referral info for a trader (referral code and direct referrer)
    function getTraderReferralInfo(address _account) external view returns (bytes32 code, address referrer);

    // @dev get the referrer chain for a trader (l1 parent and l2 parent)
    function getReferrerChain(address _account) external view returns (address l1Parent, address l2Parent);

    // @dev register a referral code (msg.sender becomes the owner)
    function registerCode(bytes32 _code) external;

    // @dev transfer a referral code to a new owner (only current owner can call)
    function transferCode(bytes32 _code, address _newOwner) external;

    // @dev bind msg.sender to a referrer via their referral code
    // auto-assigns tier 1 if user has no tier
    function bindReferrer(bytes32 _code) external;

    // @dev set the referral code for a trader (handler-only, used during order creation)
    // auto-assigns tier 1 if user has no tier
    function setTraderReferralCode(address _account, bytes32 _code) external;

    // @dev create or update a tier's rates (admin-only)
    function setTierDetail(uint256 _tierId, uint256 _l0, uint256 _l1, uint256 _l2) external;

    // @dev set the tier for a user (admin-only)
    function updateTier(address _account, uint256 _tierId) external;
}

