// SPDX-License-Identifier: BUSL-1.1

pragma solidity ^0.8.0;

import "../data/DataStore.sol";
import "../data/Keys.sol";

import "../event/EventEmitter.sol";
import "../market/MarketToken.sol";
import "../market/MarketUtils.sol";

import "./IReferralStorage.sol";
import "./ReferralEventUtils.sol";

import "../utils/Precision.sol";

// @title ReferralUtils
// @dev Library for multi-level referral functions
library ReferralUtils {
    // @dev struct to hold multi-level referral info
    struct ReferralInfo {
        bytes32 referralCode;
        address l1Affiliate;       // direct parent (B)
        address l2Affiliate;       // grandparent (A)
        uint256 traderDiscountFactor;   // trader's own tier l0 rate (as float)
        uint256 l1RewardFactor;         // l1Affiliate's tier l1 rate (as float)
        uint256 l2RewardFactor;         // l2Affiliate's tier l2 rate (as float)
    }

    // @dev set the referral code for a trader
    // @param referralStorage The referral storage instance to use.
    // @param account The account of the trader.
    // @param referralCode The referral code.
    function setTraderReferralCode(
        IReferralStorage referralStorage,
        address account,
        bytes32 referralCode
    ) internal {
        if (referralCode == bytes32(0)) { return; }
        if (address(referralStorage) == address(0)) { return; }

        referralStorage.setTraderReferralCode(account, referralCode);
    }

    // @dev Increments the affiliate's reward balance by the specified delta.
    function incrementAffiliateReward(
        DataStore dataStore,
        EventEmitter eventEmitter,
        address market,
        address token,
        address affiliate,
        uint256 delta
    ) internal {
        if (delta == 0) { return; }
        if (affiliate == address(0)) { return; }

        uint256 nextValue = dataStore.incrementUint(Keys.affiliateRewardKey(market, token, affiliate), delta);
        uint256 nextPoolValue = dataStore.incrementUint(Keys.affiliateRewardKey(market, token), delta);

        ReferralEventUtils.emitAffiliateRewardUpdated(
            eventEmitter,
            market,
            token,
            affiliate,
            delta,
            nextValue,
            nextPoolValue
        );
    }

    // @dev Gets the multi-level referral information for the specified trader.
    // @param referralStorage The referral storage instance to use.
    // @param trader The trader's address.
    // @return ReferralInfo struct with multi-level referral data
    function getReferralInfo(
        IReferralStorage referralStorage,
        address trader
    ) internal view returns (ReferralInfo memory) {
        ReferralInfo memory info;

        if (address(referralStorage) == address(0)) {
            return info;
        }

        (info.referralCode, info.l1Affiliate) = referralStorage.getTraderReferralInfo(trader);

        // no referral code means no discounts or rewards
        if (info.referralCode == bytes32(0)) {
            return info;
        }

        // get l2 affiliate (grandparent)
        (, info.l2Affiliate) = referralStorage.getReferrerChain(trader);

        // trader's own discount (l0 from their tier)
        uint256 traderTier = referralStorage.referrerTiers(trader);
        (uint256 traderL0, /*l1*/, /*l2*/) = referralStorage.getTierDetail(traderTier);
        info.traderDiscountFactor = Precision.basisPointsToFloat(traderL0);

        // l1 affiliate reward (l1 from their tier)
        if (info.l1Affiliate != address(0)) {
            uint256 l1Tier = referralStorage.referrerTiers(info.l1Affiliate);
            (, uint256 l1Rate,) = referralStorage.getTierDetail(l1Tier);
            info.l1RewardFactor = Precision.basisPointsToFloat(l1Rate);
        }

        // l2 affiliate reward (l2 from their tier)
        if (info.l2Affiliate != address(0)) {
            uint256 l2Tier = referralStorage.referrerTiers(info.l2Affiliate);
            (,, uint256 l2Rate) = referralStorage.getTierDetail(l2Tier);
            info.l2RewardFactor = Precision.basisPointsToFloat(l2Rate);
        }

        return info;
    }

    // @dev Claims affiliate rewards for the given markets and tokens and sends the rewards to the specified receiver.
    function batchClaimAffiliateRewards(
        DataStore dataStore,
        EventEmitter eventEmitter,
        address[] memory markets,
        address[] memory tokens,
        address receiver,
        address account
    ) external returns (uint256[] memory) {
        if (markets.length != tokens.length) {
            revert Errors.InvalidClaimAffiliateRewardsInput(markets.length, tokens.length);
        }

        FeatureUtils.validateFeature(dataStore, Keys.claimAffiliateRewardsFeatureDisabledKey(address(this)));

        AccountUtils.validateReceiver(receiver);

        uint256[] memory claimedAmounts = new uint256[](markets.length);

        for (uint256 i; i < markets.length; i++) {
            claimedAmounts[i] = _claimAffiliateReward(
                dataStore,
                eventEmitter,
                markets[i],
                tokens[i],
                account,
                receiver
            );
        }

        return claimedAmounts;
    }

    function _claimAffiliateReward(
        DataStore dataStore,
        EventEmitter eventEmitter,
        address market,
        address token,
        address account,
        address receiver
    ) private returns (uint256) {
        bytes32 key = Keys.affiliateRewardKey(market, token, account);

        uint256 rewardAmount = dataStore.getUint(key);
        dataStore.setUint(key, 0);

        uint256 nextPoolValue = dataStore.decrementUint(Keys.affiliateRewardKey(market, token), rewardAmount);

        MarketToken(payable(market)).transferOut(
            token,
            receiver,
            rewardAmount
        );

        MarketUtils.validateMarketTokenBalance(dataStore, market);

        ReferralEventUtils.emitAffiliateRewardClaimed(
            eventEmitter,
            market,
            token,
            account,
            receiver,
            rewardAmount,
            nextPoolValue
        );

        return rewardAmount;
    }
}

