// SPDX-License-Identifier: BUSL-1.1

pragma solidity ^0.8.0;

import "../event/EventEmitter.sol";
import "../event/EventUtils.sol";
import "../utils/Cast.sol";

library CreditEventUtils {
    using EventUtils for EventUtils.AddressItems;
    using EventUtils for EventUtils.UintItems;
    using EventUtils for EventUtils.IntItems;
    using EventUtils for EventUtils.BoolItems;
    using EventUtils for EventUtils.Bytes32Items;
    using EventUtils for EventUtils.BytesItems;
    using EventUtils for EventUtils.StringItems;

    function emitCreditOffsetApplied(
        EventEmitter eventEmitter,
        address account,
        address market,
        address token,
        uint256 amount
    ) external {
        EventUtils.EventLogData memory eventData;

        eventData.addressItems.initItems(3);
        eventData.addressItems.setItem(0, "account", account);
        eventData.addressItems.setItem(1, "market", market);
        eventData.addressItems.setItem(2, "token", token);

        eventData.uintItems.initItems(1);
        eventData.uintItems.setItem(0, "amount", amount);

        eventEmitter.emitEventLog2(
            "CreditOffsetApplied",
            Cast.toBytes32(account),
            Cast.toBytes32(market),
            eventData
        );
    }

    function emitCreditSwapped(
        EventEmitter eventEmitter,
        address account,
        uint256 amount,
        address creditToken,
        address claimToken,
        address payoutToken
    ) external {
        EventUtils.EventLogData memory eventData;

        eventData.addressItems.initItems(4);
        eventData.addressItems.setItem(0, "account", account);
        eventData.addressItems.setItem(1, "creditToken", creditToken);
        eventData.addressItems.setItem(2, "claimToken", claimToken);
        eventData.addressItems.setItem(3, "payoutToken", payoutToken);

        eventData.uintItems.initItems(1);
        eventData.uintItems.setItem(0, "amount", amount);

        eventEmitter.emitEventLog1(
            "CreditSwapped",
            Cast.toBytes32(account),
            eventData
        );
    }

    function emitCreditAdminWithdrawn(
        EventEmitter eventEmitter,
        address token,
        address receiver,
        uint256 amount
    ) external {
        EventUtils.EventLogData memory eventData;

        eventData.addressItems.initItems(2);
        eventData.addressItems.setItem(0, "token", token);
        eventData.addressItems.setItem(1, "receiver", receiver);

        eventData.uintItems.initItems(1);
        eventData.uintItems.setItem(0, "amount", amount);

        eventEmitter.emitEventLog2(
            "CreditAdminWithdrawn",
            Cast.toBytes32(token),
            Cast.toBytes32(receiver),
            eventData
        );
    }

    function emitCreditDistributionAllocated(
        EventEmitter eventEmitter,
        address account,
        uint256 amount
    ) external {
        EventUtils.EventLogData memory eventData;

        eventData.addressItems.initItems(1);
        eventData.addressItems.setItem(0, "account", account);

        eventData.uintItems.initItems(1);
        eventData.uintItems.setItem(0, "amount", amount);

        eventEmitter.emitEventLog1(
            "CreditDistributionAllocated",
            Cast.toBytes32(account),
            eventData
        );
    }

    function emitCreditDistributionClaimed(
        EventEmitter eventEmitter,
        address account,
        uint256 amount
    ) external {
        EventUtils.EventLogData memory eventData;

        eventData.addressItems.initItems(1);
        eventData.addressItems.setItem(0, "account", account);

        eventData.uintItems.initItems(1);
        eventData.uintItems.setItem(0, "amount", amount);

        eventEmitter.emitEventLog1(
            "CreditDistributionClaimed",
            Cast.toBytes32(account),
            eventData
        );
    }

    function emitCreditDistributionCleared(
        EventEmitter eventEmitter,
        address account,
        uint256 amount
    ) external {
        EventUtils.EventLogData memory eventData;

        eventData.addressItems.initItems(1);
        eventData.addressItems.setItem(0, "account", account);

        eventData.uintItems.initItems(1);
        eventData.uintItems.setItem(0, "amount", amount);

        eventEmitter.emitEventLog1(
            "CreditDistributionCleared",
            Cast.toBytes32(account),
            eventData
        );
    }

    function emitCreditDistributorEnabledSet(
        EventEmitter eventEmitter,
        bool enabled
    ) external {
        EventUtils.EventLogData memory eventData;

        eventData.boolItems.initItems(1);
        eventData.boolItems.setItem(0, "enabled", enabled);

        eventEmitter.emitEventLog(
            "CreditDistributorEnabledSet",
            eventData
        );
    }

    function emitCreditProfitFulfilled(
        EventEmitter eventEmitter,
        address receiver,
        uint256 amount,
        address payoutToken
    ) external {
        EventUtils.EventLogData memory eventData;

        eventData.addressItems.initItems(2);
        eventData.addressItems.setItem(0, "receiver", receiver);
        eventData.addressItems.setItem(1, "payoutToken", payoutToken);

        eventData.uintItems.initItems(1);
        eventData.uintItems.setItem(0, "amount", amount);

        eventEmitter.emitEventLog1(
            "CreditProfitFulfilled",
            Cast.toBytes32(receiver),
            eventData
        );
    }
}

