import "../data/Keys.sol";
import "../market/Market.sol";

// @title CreditMarketUtils
// @dev Library for detecting Credit Markets — special markets where
//      longToken == shortToken == CreditToken (the credit ERC20 stored in DataStore
//      under the CREDIT_TOKEN key). Credit Markets are used for the experience-credit
//      trading flow: users open positions with Credit Token as collateral; on close
//      the remaining collateral stays in the pool while positive PnL is atomically
//      swapped into the configured payout token (USDT) by CreditProfitClaimVault.
//
//      The detection is fully dynamic — no separate `IS_CREDIT_MARKET` storage flag
//      is used. This keeps existing market storage untouched and removes any
//      possibility of the flag drifting out of sync with the actual token triple.
library CreditMarketUtils {
    // @dev returns true if `market` is a Credit Market.
    //      Conditions:
    //        - longToken == shortToken (single-token market)
    //        - the matching token equals the configured CREDIT_TOKEN
    //      Returns false when the credit feature is disabled (CREDIT_TOKEN unset).
    //
    //      Marked `external` so that the entire detection (including the
    //      dataStore.getAddress STATICCALL bytecode) lives in this library's
    //      deployed code rather than being inlined into every caller. This
    //      keeps the size-constrained DecreasePositionCollateralUtils /
    //      PositionUtils libraries lean — at the cost of one extra DELEGATECALL
    //      per check (~700 gas), which is acceptable for the few hot paths
    //      that need it.
    function isCreditMarket(
        DataStore dataStore,
        Market.Props memory market
    ) external view returns (bool) {
        return _isCreditMarket(dataStore, market.longToken, market.shortToken);
    }

    // @dev overload that takes the long / short token addresses directly. Useful
    //      from contexts (e.g. PositionPricingUtils.GetPositionFeesParams) that
    //      already carry the token pair without a Market.Props handle.
    function isCreditMarket(
        DataStore dataStore,
        address longToken,
        address shortToken
    ) external view returns (bool) {
        return _isCreditMarket(dataStore, longToken, shortToken);
    }

    function _isCreditMarket(
        DataStore dataStore,
        address longToken,
        address shortToken
    ) private view returns (bool) {
        if (longToken != shortToken) {
            return false;
        }
        address creditToken = dataStore.getAddress(Keys.creditTokenKey());
        if (creditToken == address(0)) {
            return false;
        }
        return longToken == creditToken;
    }
}

