// SPDX-License-Identifier: BUSL-1.1

pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import "../data/DataStore.sol";
import "../data/Keys.sol";
import "../error/Errors.sol";
import "../event/EventEmitter.sol";
import "../market/MarketToken.sol";

import "./CreditEventUtils.sol";

interface ICreditFeeClaimVault {
    function isClaimTokenSupported(address claimToken) external view returns (bool);
    function tokenToCreditAmount(address claimToken, uint256 tokenAmount) external view returns (uint256);
    function creditToTokenAmount(address claimToken, uint256 creditAmount) external view returns (uint256);
    function totalClaimableCredit(address account) external view returns (uint256);
    function recordFeeOffset(address account, address claimToken, uint256 tokenAmount) external returns (uint256);
}

// @title CreditUtils
// @dev Library that performs the Credit Token (体验金) fee offset during the
//      core trading / liquidity flows.
//
//      For each one-time fee that would otherwise go to the LP (`feeAmountForPool`),
//      we check the user's Credit Token holdings and previously recorded vault
//      claimable amount. Any unmatched holding can offset up to `feeAmountForPool`
//      after converting the fee token into 18-decimal Credit units using the rate
//      configured in CreditFeeClaimVault. The vault keeps the Credit-side accounting.
library CreditUtils {
    // @dev compute and apply a credit fee offset.
    //      callers should subtract the returned `tokenOffsetAmount` from `feeAmountForPool`
    //      (and any sub-fields it consumes, e.g. `positionFeeAmountForPool`) before
    //      forwarding the residual to `applyDeltaToPoolAmount`.
    //
    // @param dataStore       protocol DataStore
    // @param eventEmitter    protocol EventEmitter
    // @param account         the user paying the fee
    // @param market          the MarketToken address that physically holds collateralToken
    // @param collateralToken the token denomination of `feeAmountForPool` (typically USDT)
    // @param feeAmountForPool LP-bound portion of the fee; offset upper bound
    //
    // @return tokenOffsetAmount the amount actually offset (in collateralToken units)
    function applyCreditFeeOffset(
        DataStore dataStore,
        EventEmitter eventEmitter,
        address account,
        address market,
        address collateralToken,
        uint256 feeAmountForPool
    ) external returns (uint256 tokenOffsetAmount) {
        if (feeAmountForPool == 0) {
            return 0;
        }

        address creditToken = dataStore.getAddress(Keys.creditTokenKey());
        if (creditToken == address(0)) {
            // credit feature not configured on this deployment
            return 0;
        }

        // skip when the fee itself is denominated in Credit Token (future credit market)
        if (collateralToken == creditToken) {
            return 0;
        }

        address feeClaimVault = dataStore.getAddress(Keys.creditFeeClaimVaultKey());
        if (feeClaimVault == address(0)) {
            revert Errors.CreditFeeClaimVaultNotSet();
        }

        {
            ICreditFeeClaimVault claimVault = ICreditFeeClaimVault(feeClaimVault);
            if (!claimVault.isClaimTokenSupported(collateralToken)) {
                return 0;
            }

            uint256 holding = IERC20(creditToken).balanceOf(account);
            if (holding == 0) {
                return 0;
            }

            uint256 existingClaimable = claimVault.totalClaimableCredit(account);
            uint256 availableCredit = holding > existingClaimable ? holding - existingClaimable : 0;
            if (availableCredit == 0) {
                return 0;
            }

            uint256 maxFeeCreditAmount = claimVault.tokenToCreditAmount(collateralToken, feeAmountForPool);
            if (maxFeeCreditAmount == 0) {
                return 0;
            }

            uint256 requestedCreditAmount = maxFeeCreditAmount < availableCredit ? maxFeeCreditAmount : availableCredit;
            tokenOffsetAmount = claimVault.creditToTokenAmount(collateralToken, requestedCreditAmount);
            if (tokenOffsetAmount == 0) {
                return 0;
            }

            uint256 recordedCreditAmount = claimVault.recordFeeOffset(account, collateralToken, tokenOffsetAmount);
            if (recordedCreditAmount == 0) {
                return 0;
            }
        }

        // physically transfer the offset amount of claim token from the MarketToken
        // to the CreditFeeClaimVault so the vault has matching reserves when the
        // user later claims.
        MarketToken(payable(market)).transferOut(collateralToken, feeClaimVault, tokenOffsetAmount);

        CreditEventUtils.emitCreditOffsetApplied(
            eventEmitter,
            account,
            market,
            collateralToken,
            tokenOffsetAmount
        );
    }
}

