pragma solidity 0.8.28;

// OpenZeppelin imports
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

// Interface imports
import {IAdapter} from "../interfaces/IAdapter.sol";
import {IVaultV2} from "../interfaces/IVaultV2.sol";
import {MathLib} from "../libraries/MathLib.sol";

import "../libraries/ConstantsLib.sol";
import "../libraries/ErrorsLib.sol";
import "../libraries/EventsLib.sol";

// ========================================= EXTERNAL INTERFACES =========================================

/**
 * @notice Maple Finance Syrup router — entry point for USDC → syrupUSDC deposits.
 * @dev Two deposit paths: plain `deposit` (when already authorised) and
 *      `authorizeAndDeposit` (first-time / re-auth via EIP-712 bitmap signature).
 */
interface ISyrupRouter {
    function deposit(
        uint256 amount,
        bytes32 depositData
    ) external returns (uint256 shares);

    function authorizeAndDeposit(
        uint256 bitmap,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s,
        uint256 amount,
        bytes32 depositData
    ) external returns (uint256 shares);
}

/**
 * @notice Maple Finance pool token (syrupUSDC) interface.
 * @dev convertToExitAssets / convertToExitShares use the exit exchange-rate,
 *      which may differ from the deposit rate during active redemption windows.
 */
interface IMaplePool {
    function balanceOf(address user) external view returns (uint256);
    function convertToExitAssets(uint256 shares) external view returns (uint256);
    function convertToExitShares(uint256 assets) external view returns (uint256);
    function requestRedeem(uint256 shares, address receiver) external returns (uint256);
}

/**
 * @notice Maple Finance withdrawal manager — tracks pending redemption requests.
 * @dev A user may have at most one active request at a time (identified by requestId).
 *      `removeSharesById` allows partial or full cancellation before the request matures.
 */
interface IMapleWithdrawalManager {
    function userEscrowedShares(address owner) external view returns (uint256);
    /// @notice Request id of an account's latest withdrawal request (0 if none).
    function requestIds(address owner) external view returns (uint256);
    /// @notice Reduce or cancel a pending request; returns escrowed LP shares to the owner.
    /// @dev If sharesToRemove == request shares the request is cancelled, else it is decreased.
    function removeSharesById(
        uint256 requestId,
        uint256 sharesToRemove
    ) external returns (uint256 sharesReturned, uint256 sharesRemaining);
}

// ========================================= CONTRACT =========================================

/**
 * @title  MapleAdapter
 * @notice Byzanlink Vault V2 adapter for the Maple Finance Syrup USDC pool.
 * @dev    Allocation deposits USDC into Maple via SyrupRouter and receives syrupUSDC
 *         shares. Deallocation is asynchronous: `deallocateAsync` opens a Maple redeem
 *         request; `deallocate` transfers settled USDC back to the vault.
 *         A configurable reserve percentage is kept idle (not deposited) to service small
 *         synchronous withdrawals without waiting for the Maple queue.
 */
contract MapleAdapter is IAdapter, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using MathLib for uint256;

    // ========================================= STATE =========================================

    address public immutable vault;
    address public owner;

    IERC20 public immutable asset;

    ISyrupRouter public router;
    IMaplePool public pool;
    IMapleWithdrawalManager public mapleWithdrawalManager;

    bytes32 public immutable adapterId;

    address public operator;

    // Reserve logic (same as nAlpha)
    uint256 public reservePercentageBps;
    uint256 private constant BPS_UNIT = 10000;

    // Maple authorization
    bool public authorized;
    uint256 public bitmap;
    uint256 public deadline;
    uint8 public v;
    bytes32 public r;
    bytes32 public s;

    bytes32 public depositData;

    // ========================================= MODIFIERS =========================================

    modifier onlyVault() {
        if (msg.sender != vault) revert ErrorsLib.NotVault();
        _;
    }

    modifier onlyOwner() {
        if (msg.sender != owner) revert ErrorsLib.NotOwner();
        _;
    }

    modifier onlyVaultOrOperator() {
        if (msg.sender != vault && msg.sender != operator)
            revert ErrorsLib.NotAuthorized();
        _;
    }

    // ========================================= CONSTRUCTOR =========================================

    constructor(
        address _vault,
        address _asset,
        address _router,
        address _pool,
        bytes32 _depositData,
        uint256 _reservePercentageBps,
        address _operator,
        address _withdrawalManager
    ) {
        if (
            _vault == address(0) ||
            _asset == address(0) ||
            _router == address(0) ||
            _pool == address(0) ||
            _withdrawalManager == address(0)
        ) revert ErrorsLib.InvalidAddress();

        if (_reservePercentageBps > MAX_RESERVE_BPS)
            revert ErrorsLib.InvalidAmount();

        vault = _vault;
        asset = IERC20(_asset);
        router = ISyrupRouter(_router);
        pool = IMaplePool(_pool);
        mapleWithdrawalManager = IMapleWithdrawalManager(_withdrawalManager);

        depositData = _depositData;

        reservePercentageBps = _reservePercentageBps;

        owner = msg.sender;
        operator = _operator;

        adapterId = keccak256(abi.encode("this", address(this)));
    }

    // ========================================= ADMIN =========================================

    function setAuthorization(
        uint256 _bitmap,
        uint256 _deadline,
        uint8 _v,
        bytes32 _r,
        bytes32 _s
    ) external onlyOwner {
        bitmap = _bitmap;
        deadline = _deadline;
        v = _v;
        r = _r;
        s = _s;
    }

    function setReservePercentage(
        uint256 _reservePercentageBps
    ) external onlyOwner {
        if (_reservePercentageBps > MAX_RESERVE_BPS)
            revert ErrorsLib.InvalidAmount();

        uint256 old = reservePercentageBps;
        reservePercentageBps = _reservePercentageBps;

        emit EventsLib.ReservePercentageUpdated(old, _reservePercentageBps);
    }

    function updateOperator(address _newOperator) external onlyOwner {
        if (_newOperator == address(0)) revert ErrorsLib.InvalidOperator();
        address oldOperator = operator;
        operator = _newOperator;
        emit EventsLib.OperatorUpdated(oldOperator, _newOperator);
    }

    function setDepositData(bytes32 _depositData) external onlyOwner {
        if (_depositData == bytes32(0)) revert ErrorsLib.InvalidData();

        bytes32 oldDepositData = depositData;
        depositData = _depositData;

        emit EventsLib.DepositDataUpdated(oldDepositData, _depositData);
    }

    function setAuthorized(bool _authorized) external onlyOwner {
        if (authorized == _authorized) revert ErrorsLib.AlreadySet();
        authorized = _authorized;
        emit EventsLib.AuthorizedUpdated(authorized);
    }

    function setWithdrawalManager(
        address _withdrawalManager
    ) external onlyOwner {
        if (_withdrawalManager == address(0)) revert ErrorsLib.InvalidAddress();
        if (_withdrawalManager == address(mapleWithdrawalManager))
            revert ErrorsLib.AlreadySet();
        address oldWithdrawalManager = address(mapleWithdrawalManager);
        mapleWithdrawalManager = IMapleWithdrawalManager(_withdrawalManager);
        emit EventsLib.WithdrawalManagerUpdated(
            oldWithdrawalManager,
            _withdrawalManager
        );
    }

    function setPool(address _pool) external onlyOwner {
        if (_pool == address(0)) revert ErrorsLib.InvalidAddress();
        if (_pool == address(pool)) revert ErrorsLib.AlreadySet();
        address oldPool = address(pool);
        pool = IMaplePool(_pool);
        emit EventsLib.PoolUpdated(oldPool, _pool);
    }

    function setRouter(address _router) external onlyOwner {
        if (_router == address(0)) revert ErrorsLib.InvalidAddress();
        if (_router == address(router)) revert ErrorsLib.AlreadySet();
        address oldRouter = address(router);
        router = ISyrupRouter(_router);
        emit EventsLib.RouterUpdated(oldRouter, _router);
    }

    function setOwner(address _newOwner) external onlyOwner {
        if (_newOwner == address(0)) revert ErrorsLib.InvalidAddress();
        owner = _newOwner;
        emit EventsLib.SetOwner(_newOwner);
    }

    // ========================================= ALLOCATE =========================================

    function allocate(
        bytes memory data,
        uint256 assets,
        bytes4,
        address
    )
        external
        override
        onlyVaultOrOperator
        nonReentrant
        returns (bytes32[] memory, int256 change)
    {
        if (assets == 0) revert ErrorsLib.InvalidAmount();

        uint256 disableReserve = data.length == 0
            ? 0
            : abi.decode(data, (uint256));
        uint256 reserveAmount = disableReserve == 0
            ? assets.mulDivDown(reservePercentageBps, BPS_UNIT)
            : 0;

        uint256 assetsToDeposit = assets - reserveAmount;

        uint256 oldAllocation = allocation();

        SafeERC20.forceApprove(asset, address(router), assetsToDeposit);

        uint256 shares;

        if (authorized) {
            shares = router.deposit(assetsToDeposit, depositData);
        } else {
            // IMPORTANT: set before call to avoid race
            authorized = true;

            shares = router.authorizeAndDeposit(
                bitmap,
                deadline,
                v,
                r,
                s,
                assetsToDeposit,
                depositData
            );
        }

        uint256 newAllocation = _realAssets();
        int256 allocationChange = int256(newAllocation) - int256(oldAllocation);

        emit EventsLib.Allocated(
            assets,
            shares,
            allocationChange,
            reserveAmount
        );

        return (ids(), allocationChange);
    }

    // ========================================= DEALLOCATE =========================================

    function deallocateAsync(
        bytes memory,
        uint256 assets,
        bytes4,
        address sender
    ) external onlyVaultOrOperator nonReentrant {
        if (assets == 0) revert ErrorsLib.InvalidAmount();

        uint256 shares = pool.convertToExitShares(assets);

        shares = MathLib.min(shares, pool.balanceOf(address(this)));

        if (shares == 0) revert ErrorsLib.InvalidAmount();

        pool.requestRedeem(shares, address(this));

        // `requestRedeem` returns escrowed shares, not the request id. The queue tracks
        // the owner's active request id, so read it back so it can be logged and later
        // used to cancel the request.
        uint256 requestId = mapleWithdrawalManager.requestIds(address(this));

        emit EventsLib.WithdrawalRequestCreated(
            sender,
            shares,
            0,
            uint64(block.timestamp),
            requestId
        );
    }

    function deallocate(
        bytes memory,
        uint256 assets,
        bytes4,
        address
    )
        external
        override
        onlyVault
        nonReentrant
        returns (bytes32[] memory, int256)
    {
        if (assets == 0) revert ErrorsLib.InvalidAmount();
        if (asset.balanceOf(address(this)) < assets)
            revert ErrorsLib.InsufficientAssets();

        SafeERC20.forceApprove(asset, vault, assets);

        uint256 oldAllocation = allocation();
        uint256 newAllocation = _realAssets() - assets;

        emit EventsLib.Deallocated(assets);

        return (ids(), int256(newAllocation) - int256(oldAllocation));
    }

    // ========================================= ACCOUNTING =========================================

    function _realAssets() internal view returns (uint256 assets) {
        uint256 activeShares = pool.balanceOf(address(this));
        uint256 escrowedShares = mapleWithdrawalManager.userEscrowedShares(
            address(this)
        );
        assets = pool.convertToExitAssets(activeShares + escrowedShares);
        assets += asset.balanceOf(address(this));
    }

    function realAssets() external view override returns (uint256) {
        return _realAssets();
    }

    function allocation() public view returns (uint256) {
        return IVaultV2(vault).allocation(adapterId);
    }

    function ids() public view returns (bytes32[] memory) {
        bytes32[] memory ids_ = new bytes32[](1);
        ids_[0] = adapterId;
        return ids_;
    }

    /**
     * @notice Hook invoked by the vault when withdrawals are cancelled. The Maple deposit
     *         flow resets the router allowance on every allocate, so there is no lingering
     *         allowance to revoke here. Cancelling the underlying Maple redeem request is a
     *         distinct action handled by {cancelWithdrawalRequest}.
     */
    function validateAndRevokeAllowance(
        uint256
    )
        external
        override
        onlyVault
        returns (bool isValid, uint256 revokedShares)
    {
        emit EventsLib.AtomicRequestRevokedAllowance(true, 0);
        return (true, 0);
    }

    /**
     * @notice Cancels (fully or partially) the adapter's pending Maple redeem request.
     * @param assets Asset value to cancel from the pending request. Pass 0 to cancel the
     *               entire request.
     * @return cancelled True when a request was cancelled or reduced; false when there was
     *                   nothing to cancel (no active request).
     * @return revokedShares LP shares returned to the adapter from the cancelled portion.
     */
    function cancelWithdrawalRequest(
        uint256 assets
    )
        external
        onlyVaultOrOperator
        nonReentrant
        returns (bool cancelled, uint256 revokedShares)
    {
        uint256 requestId = mapleWithdrawalManager.requestIds(address(this));
        uint256 escrowedShares = mapleWithdrawalManager.userEscrowedShares(
            address(this)
        );

        // No active request (or nothing escrowed) → nothing to cancel.
        if (requestId == 0 || escrowedShares == 0) {
            return (false, 0);
        }

        // assets == 0 cancels the whole request; otherwise cancel just the requested
        // value, capped to what is actually escrowed.
        uint256 sharesToRemove = assets == 0
            ? escrowedShares
            : MathLib.min(pool.convertToExitShares(assets), escrowedShares);

        if (sharesToRemove == 0) {
            return (false, 0);
        }

        (revokedShares, ) = mapleWithdrawalManager.removeSharesById(
            requestId,
            sharesToRemove
        );

        emit EventsLib.WithdrawalRequestCancelled(requestId, revokedShares);
        return (true, revokedShares);
    }
}

