allocate:
function allocate(
        bytes memory data,
        uint256 assets,
        bytes4,
        address
    )
        external
        override
        onlyVaultOrOperator
        nonReentrant
        returns (bytes32[] memory, int256 change)
    {
        if (assets == 0) revert ErrorsLib.InvalidAmount();

        uint256 disableReserve = data.length == 0
            ? 0
            : abi.decode(data, (uint256));
        uint256 reserveAmount = disableReserve == 0
            ? assets.mulDivDown(reservePercentageBps, BPS_UNIT)
            : 0;

        uint256 assetsToDeposit = assets - reserveAmount;

        uint256 oldAllocation = allocation();

        SafeERC20.forceApprove(asset, address(router), assetsToDeposit);

        uint256 shares;

        if (authorized) {
            shares = router.deposit(assetsToDeposit, depositData);
        } else {
            // IMPORTANT: set before call to avoid race
            authorized = true;

            shares = router.authorizeAndDeposit(
                bitmap,
                deadline,
                v,
                r,
                s,
                assetsToDeposit,
                depositData
            );
        }

        uint256 newAllocation = _realAssets();
        int256 allocationChange = int256(newAllocation) - int256(oldAllocation);

        emit EventsLib.Allocated(
            assets,
            shares,
            allocationChange,
            reserveAmount
        );

        return (ids(), allocationChange);
    }

deallocate:
function deallocate(
        bytes memory,
        uint256 assets,
        bytes4,
        address
    )
        external
        override
        onlyVault
        nonReentrant
        returns (bytes32[] memory, int256)
    {
        if (assets == 0) revert ErrorsLib.InvalidAmount();
        if (asset.balanceOf(address(this)) < assets)
            revert ErrorsLib.InsufficientAssets();

        SafeERC20.forceApprove(asset, vault, assets);

        uint256 oldAllocation = allocation();
        uint256 newAllocation = _realAssets() - assets;

        emit EventsLib.Deallocated(assets);

        return (ids(), int256(newAllocation) - int256(oldAllocation));
    }

deallocateAsync:
function deallocateAsync(
        bytes memory,
        uint256 assets,
        bytes4,
        address sender
    ) external onlyVaultOrOperator nonReentrant {
        if (assets == 0) revert ErrorsLib.InvalidAmount();

        uint256 shares = pool.convertToExitShares(assets);

        shares = MathLib.min(shares, pool.balanceOf(address(this)));

        if (shares == 0) revert ErrorsLib.InvalidAmount();

        pool.requestRedeem(shares, address(this));

        // `requestRedeem` returns escrowed shares, not the request id. The queue tracks
        // the owner's active request id, so read it back so it can be logged and later
        // used to cancel the request.
        uint256 requestId = mapleWithdrawalManager.requestIds(address(this));

        emit EventsLib.WithdrawalRequestCreated(
            sender,
            shares,
            0,
            uint64(block.timestamp),
            requestId
        );
    }

_realAssets:
function _realAssets() internal view returns (uint256 assets) {
        uint256 activeShares = pool.balanceOf(address(this));
        uint256 escrowedShares = mapleWithdrawalManager.userEscrowedShares(
            address(this)
        );
        assets = pool.convertToExitAssets(activeShares + escrowedShares);
        assets += asset.balanceOf(address(this));
    }

allocation:
function allocation() public view returns (uint256) {
        return IVaultV2(vault).allocation(adapterId);
    }

ids:
function ids() public view returns (bytes32[] memory) {
        bytes32[] memory ids_ = new bytes32[](1);
        ids_[0] = adapterId;
        return ids_;
    }

allocate:
function allocate(address adapter, bytes memory data, uint256 assets) external {
        require(isAllocator[msg.sender], ErrorsLib.Unauthorized());
        allocateInternal(adapter, data, assets);
    }

allocateInternal:
function allocateInternal(address adapter, bytes memory data, uint256 assets) internal {
        require(isAdapter[adapter], ErrorsLib.NotAdapter());

        accrueInterest();

        SafeERC20Lib.safeTransfer(asset, adapter, assets);
        (bytes32[] memory ids, int256 change) = IAdapter(adapter).allocate(data, assets, msg.sig, msg.sender);

        for (uint256 i; i < ids.length; i++) {
            Caps storage _caps = caps[ids[i]];
            _caps.allocation = (int256(_caps.allocation) + change).toUint256();

            require(_caps.absoluteCap > 0, ErrorsLib.ZeroAbsoluteCap());
            require(_caps.allocation <= _caps.absoluteCap, ErrorsLib.AbsoluteCapExceeded());
            require(
                _caps.relativeCap == WAD || _caps.allocation <= firstTotalAssets.mulDivDown(_caps.relativeCap, WAD),
                ErrorsLib.RelativeCapExceeded()
            );
        }
        emit EventsLib.Allocate(msg.sender, adapter, assets, ids, change);
    }

deallocate:
function deallocate(address adapter, bytes memory data, uint256 assets) external {
        require(isAllocator[msg.sender] || isSentinel[msg.sender], ErrorsLib.Unauthorized());
        deallocateInternal(adapter, data, assets);
    }

deallocateInternal:
function deallocateInternal(address adapter, bytes memory data, uint256 assets)
        internal
        returns (bytes32[] memory)
    {
        require(isAdapter[adapter], ErrorsLib.NotAdapter());

        (bytes32[] memory ids, int256 change) = IAdapter(adapter).deallocate(data, assets, msg.sig, msg.sender);

        for (uint256 i; i < ids.length; i++) {
            Caps storage _caps = caps[ids[i]];
            require(_caps.allocation > 0, ErrorsLib.ZeroAllocation());
            _caps.allocation = (int256(_caps.allocation) + change).toUint256();
        }

        SafeERC20Lib.safeTransferFrom(asset, adapter, address(this), assets);
        emit EventsLib.Deallocate(msg.sender, adapter, assets, ids, change);
        return ids;
    }

deallocateAsync:
function deallocateAsync(address adapter, bytes memory data, uint256 assets) external {
         require(isOperator[msg.sender], ErrorsLib.Unauthorized());
         deallocateInternalAsync(adapter, data, assets);
    }

deallocateInternalAsync:
function deallocateInternalAsync(address adapter, bytes memory data, uint256 assets) internal   {
        require(isAdapter[adapter], ErrorsLib.NotAdapter());
        IAdapter(adapter).deallocateAsync(data, assets, "", msg.sender);
        emit EventsLib.DeallocateAsync(msg.sender, adapter, assets, assets);
    }

modules/syrup-router/contracts/SyrupRout:
function deposit(uint256 amount_, bytes32 depositData_) external override returns (uint256 shares_) {
        shares_ = _deposit(msg.sender, amount_, depositData_);
    }

function _deposit(address owner_, uint256 amount_, bytes32 depositData_) internal returns (uint256 shares_) {
        // Check the owner has permission to deposit into the pool.
        require(
            IPoolPermissionManagerLike(poolPermissionManager).hasPermission(poolManager, owner_, "P:deposit"),
            "SR:D:NOT_AUTHORIZED"
        );

        // Pull assets from the owner to the router.
        require(ERC20Helper.transferFrom(asset, owner_, address(this), amount_), "SR:D:TRANSFER_FROM_FAIL");

        // Deposit assets into the pool and receive the shares personally.
        address pool_ = pool;

        shares_ = IPoolLike(pool_).deposit(amount_, address(this));

        // Route shares back to the caller.
        require(ERC20Helper.transfer(pool_, owner_, shares_), "SR:D:TRANSFER_FAIL");

        emit DepositData(owner_, amount_, depositData_);
    }

function authorizeAndDeposit(
        uint256 bitmap_,
        uint256 deadline_,
        uint8   auth_v,
        bytes32 auth_r,
        bytes32 auth_s,
        uint256 amount_,
        bytes32 depositData_
    )
        external override returns (uint256 shares_)
    {
        _authorize(deadline_, bitmap_, auth_v, auth_r, auth_s);

        shares_ = _deposit(msg.sender, amount_, depositData_);
    }

function _authorize(uint256 deadline_, uint256 bitmap_, uint8 v_, bytes32 r_, bytes32 s_) internal {
        require(deadline_ >= block.timestamp, "SR:A:EXPIRED");

        // Appendix F in the Ethereum Yellow paper (https://ethereum.github.io/yellowpaper/paper.pdf), defines
        // the valid range for s in (301): 0 < s < secp256k1n ÷ 2 + 1, and for v in (302): v ∈ {27, 28}.
        require(
            uint256(s_) <= uint256(0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) &&
            (v_ == 27 || v_ == 28),
            "SR:A:MALLEABLE"
        );

        bytes32 digest_ = keccak256(abi.encodePacked(
            "\x19\x01",
            block.chainid,  // Chain id + address(this) serves as domain separator to avoid replay attacks.
            address(this),
            msg.sender,
            nonces[msg.sender]++,
            bitmap_,
            deadline_
        ));

        address recoveredAddress_ = ecrecover(digest_, v_, r_, s_);

        IPoolPermissionManagerLike ppm_ = IPoolPermissionManagerLike(poolPermissionManager);

        // Any valid permission admin can authorize the deposit.
        require(recoveredAddress_ != address(0) && ppm_.permissionAdmins(recoveredAddress_), "SR:A:NOT_PERMISSION_ADMIN");

        address[] memory lender = new address[](1);
        uint256[] memory bitmap = new uint256[](1);

        lender[0] = msg.sender;
        bitmap[0] = bitmap_;

        ppm_.setLenderBitmaps(lender, bitmap);
    }

